local SceneManager = CS.UnityEngine.SceneManagement.SceneManager
local SceneManagement = CS.UnityEngine.SceneManagement
local KTool = CS.Engine.Lib.KTool
local IgnoreControl = CS.Engine.Modules.IgnoreControl
local PrefabLightMapData = CS.Game.Native.Common.PrefabLightMapData
local cs_coroutine = require('XLua.cs_coroutine')
---@class SceneInstance
local SceneInstance = Class('SceneInstance')

---__init
--- 参数1 --id
--- 参数2 --env
--- 参数3 --scene
function SceneInstance:__init(...)
    self._enable = true
    self._activeObjects = {}
    self._sceneLoader = nil
    self.isReleaseNow = true
    self._lightmapObjects = {} --- 光照贴图的对象
    self.identifier = table.unpack(..., 1)
    ---@type UnityEngine.SceneManagement.Scene
    self._unityScene = table.unpack(..., 2)
    ---脚本的env，用来做初始化运算的相关的逻辑
    self._sceneLoader = table.unpack(..., 3)

    if self._unityScene then
        local rootObjects = self._unityScene:GetRootGameObjects();
        for i, v in array_pairs(rootObjects) do
            if not KTool.IsNull(v) then
                local lightmapData = KTool.GetComponent(v, typeof(PrefabLightMapData))
                if not isNull(lightmapData) then
                    ---存在光照贴图对象
                    self._lightmapObjects[v.name] = v
                elseif KTool.IsActive(v) then
                    table.insert(self._activeObjects, v)
                end
            end
        end
    end
end

function SceneInstance:__delete()
    self._unityScene = nil
    self._enable = false
    self._activeObjects = nil
    self._lightmapObjects = nil
    self._sceneLoader = nil
    self.identifier = nil
    self.Env = nil
end

function SceneInstance:Identifier()
    return self.identifier
end

---@return UnityEngine.SceneManagement.Scene
function SceneInstance:GetScene()
    return self._unityScene
end

---AddCacheObject
---添加一个对象到cache列表中去
---@param go UnityEngine.GameObject
function SceneInstance:AddCacheObject(go)
    if isNull(go) then
        return
    end
    self:RemoveCacheObjectByName(go.name)
    table.insert(self._activeObjects, go)
end

---RemoveCacheObjectByName
---删除一个对象到cache列表中
---@param name string
function SceneInstance:RemoveCacheObjectByName(name)
    for i, v in pairs(self._activeObjects) do
        if KTool.IsNull(v) then
            table.remove(self._activeObjects, i)
        else
            if v.name == name then
                table.remove(self._activeObjects, i)
                return
            end
        end
    end
end

---GetCacheObjectByName
---获取指字的场景对像
---@param name string
---@return UnityEngine.GameObject
function SceneInstance:GetCacheObjectByName(name)
    local go
    for _, v in pairs(self._activeObjects) do
        if not isNull(v) then
            if v.name == name then
                go = v
                break
            end
        end
    end
    return go
end

function SceneInstance:Enable(lightType)
    if isNull(self._unityScene) then
        return false
    end
    if self._enable then
        ---如果已启动情况下，但lightType类型不为空时
        if not isNull(lightType) then
            for _, lightmapDataObject in pairs(self._lightmapObjects) do
                if lightmapDataObject and lightmapDataObject.name == lightType then
                    KTool.SetActive(lightmapDataObject, true)
                else
                    KTool.SetActive(lightmapDataObject, false)
                end
            end
        end
        return true
    end
    if table.length(self._activeObjects) == 0 then
        return true
    end
    if (not self._unityScene.isLoaded) or (not self._unityScene:IsValid()) then
        return false
    end
    SceneManagement.SceneManager.SetActiveScene(self._unityScene)
    for i, v in pairs(self._activeObjects) do
        if not isNull(v) then
            ---@type Engine.Modules.IgnoreControl
            local ignoreControl = KTool.GetComponent(v, typeof(IgnoreControl))
            if not isNull(ignoreControl) then
                if ignoreControl.Type ~= IgnoreControl.IgnoreType.ActiveControl then
                    KTool.SetActive(v, true)
                end
            else
                KTool.SetActive(v, true)
            end
        end
    end
    for _, lightmapDataObject in pairs(self._lightmapObjects) do
        if lightmapDataObject and lightmapDataObject.name == lightType then
            KTool.SetActive(lightmapDataObject, true)
        else
            KTool.SetActive(lightmapDataObject, false)
        end
    end
    self._enable = true
    return true
end

---Disable
---不显示所有的对象
function SceneInstance:Disable(lightType)
    if isNull(self._unityScene) then
        return false
    end
    if not self._enable then
        return true
    end
    if table.length(self._activeObjects) == 0 then
        return true
    end
    if (not self._unityScene.isLoaded) or (not self._unityScene:IsValid()) then
        return false
    end
    for _, lightmapDataObject in pairs(self._lightmapObjects) do
        --if lightmapDataObject and lightmapDataObject.name == lightType then
        KTool.SetActive(lightmapDataObject, false)
        --end
    end
    for i, v in pairs(self._activeObjects) do
        if not isNull(v) then
            ---@type Engine.Modules.IgnoreControl
            local ignoreControl = KTool.GetComponent(v, typeof(IgnoreControl))
            if not isNull(ignoreControl) then
                if ignoreControl.Type ~= IgnoreControl.IgnoreType.ActiveControl then
                    KTool.SetActive(v, false)
                end
            else
                KTool.SetActive(v, false)
            end
        end
    end

    self._enable = false
    return true
end

---@param objName string
---@return UnityEngine.GameObject | nil
function SceneInstance:GetRootObjByName(objName)
    if self._unityScene then
        local objResult = nil
        local rootObjects = self._unityScene:GetRootGameObjects()
        for i, v in array_pairs(rootObjects) do
            if not KTool.IsNull(v) then
                if v.name == objName then
                    objResult = v
                    break
                end
            end
        end
        return objResult
    end
    return nil
end

---@param nodePath string
---@return UnityEngine.GameObject | nil
function SceneInstance:GetSceneElement(nodePath)
    local pathList = string.split2(nodePath, "/")
    local rootName = table.remove(pathList, 1)
    local rootNode = self:GetRootObjByName(rootName)
    if not isNull(rootNode) then
        if #pathList > 0 then
            local cellPath = table.concat(pathList, "/")
            local trans = rootNode.transform:Find(cellPath)
            if not isNull(rootNode) then
                return trans.gameObject
            end
        else
            return rootNode.gameObject
        end
    end
    return nil
end

function SceneInstance:SetIsNow(isNow)
    self.isReleaseNow = checkBool(isNow)
end

---UnloadScene
---需要协程进行调用
function SceneInstance:UnloadScene()
    if self._sceneLoader then
        self._sceneLoader:Release(self.isReleaseNow)
        self._sceneLoader = nil ---置空一下
    end
    cs_coroutine.yield_return(SceneManager.UnloadSceneAsync(self._unityScene))
    self:Delete() --清除资源
end

function SceneInstance:GetEnable()
    return self._enable
end

return SceneInstance